    if (pranks.length > 0) {
        vm.stopPrank();
        pranks.pop();

        if (pranks.length > 0) {
            vm.startPrank(pranks[pranks.length - 1]);
        }
    }
}

function popAllPranks() public {
    while (pranks.length > 0) {
        popPrank();
    }
}

